import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"47、【困】 坎下兌上","description":"子夏易傳 - 47、【困】 坎下兌上","frontmatter":{"title":"47、【困】 坎下兌上","description":"子夏易傳 - 47、【困】 坎下兌上"},"headers":[],"relativePath":"classics/zixia/049.md","filePath":"classics/zixia/049.md"}'),i={name:"classics/zixia/049.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_47、【困】-坎下兌上" tabindex="-1">47、【困】 坎下兌上 <a class="header-anchor" href="#_47、【困】-坎下兌上" aria-label="Permalink to “47、【困】 坎下兌上”">​</a></h1><p>卦辭：困，亨貞，大人吉。無咎。有言不信。</p><p>彖曰：困，剛揜也。險以説，困而不失其所，亨。其唯君子乎，貞大人吉，以剛中也。有言不信，尚口乃窮也。</p><p>子夏：剛則困，見揜於柔也。險而能説，雖困而通也。君子之行，存乎素也。困而自辨，而不責於人，修齊其徳以自濟也。五為眾之歸焉。剛而能幹，中而得當，大人之正也。亨困而吉，何咎之有乎。困而尚口，斯窮之矣，何所信乎，故君子飾行以亨困，而不以言也。</p><p>象曰：澤無水，困。君子以致命遂志。</p><p>子夏：澤無水，涸而無潤也。夫積行以成其徳，雖致命，終遂其道。君子之志，剛而不可拔也，故能致困而不可失其道也。</p><p>初六，臀困於株，木入於幽谷，三嵗不覿。</p><p>象曰：入於幽谷，幽不明也。</p><p>子夏：能濟困者，剛直也。初以柔弱居於困窮，而不安其所也。而欲上應於二，為二所吝，幽於坎底，以至於三嵗而無所見，不明之至也。</p><p>九二，困於酒食，朱紱方來，利用亨祀，徵兇，無咎。</p><p>象曰：困於酒食，中有慶也。</p><p>子夏：剛而得中，為初三之附，豐於所資，困酒食者矣。酒食困，有位而得其民，則受其命服，而朱紱來矣。夫以位卑而有民利，潔敬以奉上，恃權而淩徵之兇也。卑以自守，得無咎矣。</p><p>六三，困於石，據於蒺藜，入於其宮，不見其妻。兇。</p><p>象曰：據於蒺藜，乘剛也。入於其宮，不見其妻，不祥也。</p><p>子夏：柔以居困，力不堪也。欲其往而困於四堅於石也。欲其安而據於二難於蒺藜也。進退無可安所存乎，以至於失位而殞身也。位之不當，不足亨，困不祥之至也。</p><p>九四，來徐徐，困於金車，吝有終。</p><p>象曰：來徐徐，志在下也。雖不當位，有與也。</p><p>子夏：初為之，應二剛困之，故遲遲而來，以待其間也。位之不當，不足亨，困可惜也。雖困於二，終歸其應，金車剛而能載也。</p><p>九五，劓刖，困於赤紱，乃徐有説，利用祭祀。</p><p>象曰：劓刖，志未得也。乃徐有説，以中直也。利用祭祀，受福也。</p><p>子夏：物莫能兩大，二之豐則五道減矣。二以剛得眾，而五怒其甚也。將欲刑之上，下敵應不能勝也，故困之免矣。夫居尊以忿失其道也。終以中直久而説矣。至誠感神，況赤紱乎。故精意乃受其祐矣。</p><p>上六，困於葛藟，於臲卼，曰動悔有悔。徵吉。</p><p>象曰：困於葛藟，未當也。動悔有悔，吉行也。</p><p>子夏：柔之為物，不能通於困，當困之終然，可徵矣。居於上，而果於剛，欲其退也。為葛藟係之，欲其處也。臲卼而難據，皆不離於困也。柔弱質也，不能專斷，語其治也。何哉曰動悔有悔，其處也，則徵矣，乃吉行也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
